-- #683: one `rail_` family for everything provider-facing.
--
-- The remote-facing axis was spelled three ways (provider_*, rail_*,
-- external_provider_*), and the two identity tables hid that they are mirror
-- images: rail_merchant_accounts = the MERCHANT's account at a rail (acct_...,
-- NMI Gateway ID, clientAccnum/subacc, recipient wallet);
-- rail_customer_accounts = the CUSTOMER's record at a rail (cus_... —
-- Stripe-only in practice, #682). Every row answers "WHOSE account at WHICH
-- rail". Hard cut, no aliases (#649/#650/#652 discipline).
--
-- Bare "merchant account" / "customer account" (no rail_ prefix) are RESERVED
-- platform-tier nouns for the two-party openrails.com platform; the platform_*
-- family is reserved alongside (see #683).
--
-- Stored merchant-secret NAMES are renamed too (pre-launch hard cut, Paul
-- 2026-07-01): DB-backed names below; Vault-backed deployments must move KV
-- entries provider_accounts/* -> rail_merchant_accounts/* at upgrade (operator
-- step; there are none pre-launch).

-- --- table renames ---
ALTER TABLE openrails.payment_provider_accounts RENAME TO rail_merchant_accounts;
ALTER TABLE openrails.rail_customers RENAME TO rail_customer_accounts;
ALTER TABLE openrails.provider_intents RENAME TO rail_intents;
ALTER TABLE openrails.external_provider_mutation_logs RENAME TO rail_mutation_logs;
ALTER TABLE openrails.provider_refresh_watermarks RENAME TO rail_refresh_watermarks;

-- --- column renames ---
ALTER TABLE openrails.checkout_sessions RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.rail_mutation_logs RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.invoice_payments RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.payment_methods RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.payments RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.rail_intents RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.rail_refresh_watermarks RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.rail_customer_accounts RENAME COLUMN provider_account_id TO rail_merchant_account_id;
ALTER TABLE openrails.subscriptions RENAME COLUMN provider_account_id TO rail_merchant_account_id;
-- symmetric remote-id column: (merchant_id, rail, account_id) in both identity tables
ALTER TABLE openrails.rail_customer_accounts RENAME COLUMN rail_customer_id TO account_id;

