-- --- stored secret-name prefix (DB-backed store + audit trail) ---
UPDATE openrails.merchant_secrets
   SET name = 'rail_merchant_accounts' || substr(name, length('provider_accounts') + 1)
 WHERE name LIKE 'provider_accounts/%';
UPDATE openrails.merchant_credential_audit
   SET name = 'rail_merchant_accounts' || substr(name, length('provider_accounts') + 1)
 WHERE name LIKE 'provider_accounts/%';
